function debugLog(message, data = null, category = 'INFO') {
  const timestamp = new Date().toISOString();
  const logEntry = `[${timestamp}] [${category}] ${message}\n`;

  // Color coding for different categories
  let color = '\x1b[36m'; // Cyan default
