  if (category === 'MCP') color = '\x1b[35m'; // Magenta
  if (category === 'HEARTBEAT') color = '\x1b[90m'; // Gray

  console.log(color + logEntry.trim() + '\x1b[0m');

  fs.appendFileSync(DEBUG_LOG, logEntry);

  if (data) {
    const dataStr = typeof data === 'string' ? data : JSON.stringify(data, null, 2);
    console.log(color + dataStr + '\x1b[0m');
    fs.appendFileSync(DEBUG_LOG, dataStr + '\n');
  }

  messageLog.push({ timestamp, category, message, data });
  if (messageLog.length > 1000) messageLog.shift();
}

