  debugLog(`🌐 ${req.method} ${req.url}`, null, category);
  debugLog('📋 Headers:', req.headers, category);

  if (req.method === 'POST' && req.body) {
    debugLog('📦 Body:', req.body, 'POST');
  }

  // Track response
  const originalJson = res.json;
  const originalEnd = res.end;

  res.json = function(data) {
    debugLog(`📤 Response ${res.statusCode}:`, data, category);
    return originalJson.call(this, data);
  };

  res.end = function(data) {
    if (data) {
      debugLog(`📤 Response end ${res.statusCode}:`, data.toString().substring(0, 200), category);
    }
    return originalEnd.apply(this, arguments);
  };

  next();
});

