      debugLog('⚠️ emacsclient failed, trying emacs batch:', clientError.message, 'MCP');

      const batchCommand = `emacs --batch --eval "${lispCode.replace(/"/g, '\\"')}" 2>&1`;
      const { stdout, stderr } = await execAsync(batchCommand, { timeout: 10000 });

      if (stderr) debugLog('⚠️ Emacs batch stderr:', stderr, 'MCP');

      let result = stdout.trim();

      if (result.startsWith('#("')) {
        result = result.replace(/#\("([^"]*)"/s, '$1');
        result = result.replace(/\s+\d+\s+\d+\s+\(.*?\)\s*\)+$/s, '');
      } else if (result.startsWith('"')) {
        result = result.replace(/^"(.*)"$/s, '$1');
      }

      return result;
    }
  } catch (error) {
    debugLog('💥 Emacs error:', error.message, 'ERROR');
    return `Error: ${error.message}. Make sure Emacs is installed and running.`;
  }
}

// ============================================
// SSE ENDPOINT - Main connection point
// ============================================
app.get('/sse', (req, res) => {
  const sessionId = crypto.randomBytes(16).toString('hex');
  const shortId = sessionId.substring(0, 8);
  const clientIp = req.headers['x-forwarded-for'] || req.socket.remoteAddress;

  debugLog(`🟢 SSE CLIENT CONNECTED - Session: ${shortId}, IP: ${clientIp}`, null, 'SSE');
  debugLog('🔌 Connection details:', {
    protocol: req.protocol,
    host: req.headers.host,
    origin: req.headers.origin,
    'user-agent': req.headers['user-agent'],
    'mcp-protocol-version': req.headers['mcp-protocol-version'],
    'x-title': req.headers['x-title']
  }, 'SSE');

  // Store the client with session ID
  sseClients.set(sessionId, {
    res,
    connectedAt: new Date().toISOString(),
    ip: clientIp,
    userAgent: req.headers['user-agent']
  });

  connectionLog.push({
    sessionId: shortId,
    event: 'connect',
    timestamp: new Date().toISOString(),
    ip: clientIp
  });

  debugLog(`📊 Total clients: ${sseClients.size}`, null, 'SSE');
  debugLog(`🗂️ Active sessions: ${Array.from(sseClients.keys()).map(id => id.substring(0, 8)).join(', ')}`, null, 'SSE');

  // Set SSE headers exactly as SDK expects
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Title, MCP-Protocol-Version',
    'X-Accel-Buffering': 'no' // Disable proxy buffering
  });

  // Send endpoint event with FULL URL - CRITICAL for SDK
  const messageEndpoint = `http://localhost:${port}/messages?sessionId=${sessionId}`;
  debugLog(`📨 Sending endpoint event: ${messageEndpoint}`, null, 'SSE');
  res.write(`event: endpoint\ndata: ${messageEndpoint}\n\n`);

  // Send initialized event
  debugLog(`📨 Sending initialized event`, null, 'SSE');
  res.write(`event: initialized\ndata: ${JSON.stringify({})}\n\n`);

  // Force flush headers immediately
  res.flushHeaders();

  debugLog(`⏳ Waiting for POST requests on /messages for session ${shortId}`, null, 'SSE');

  // Set timeout warning if no POST received
  const timeoutWarning = setTimeout(() => {
    if (sseClients.has(sessionId)) {
      debugLog(`⚠️ No POST requests received for session ${shortId} after 5 seconds`, null, 'SSE');
      debugLog(`   Check if Cherry Studio is configured as SSE with URL: http://localhost:${port}/sse`, null, 'SSE');
    }
  }, 5000);

  // Keep connection alive with heartbeats
  const heartbeatInterval = setInterval(() => {
    if (sseClients.has(sessionId)) {
      res.write(': heartbeat\n\n');
      debugLog(`💓 Heartbeat sent to session ${shortId}`, null, 'HEARTBEAT');
    }
  }, 15000);

  // Handle client disconnect
  req.on('close', () => {
    debugLog(`🔴 SSE CLIENT DISCONNECTED - Session ${shortId}`, null, 'SSE');
    debugLog(`   Connection duration: ${(Date.now() - new Date(sseClients.get(sessionId)?.connectedAt).getTime()) / 1000}s`, null, 'SSE');

    connectionLog.push({
      sessionId: shortId,
      event: 'disconnect',
      timestamp: new Date().toISOString()
    });

    sseClients.delete(sessionId);
    debugLog(`📊 Remaining clients: ${sseClients.size}`, null, 'SSE');

    clearTimeout(timeoutWarning);
    clearInterval(heartbeatInterval);
  });
});

// ============================================
// MESSAGES ENDPOINT - For client POST requests
// ============================================
app.post('/messages', async (req, res) => {
  const sessionId = req.query.sessionId;
  const shortId = sessionId ? sessionId.substring(0, 8) : 'unknown';

  debugLog(`📥 POST /messages received for session ${shortId}`, null, 'POST');
  debugLog('🔍 Query params:', req.query, 'POST');
  debugLog('🔍 Headers:', {
    'content-type': req.headers['content-type'],
    'content-length': req.headers['content-length'],
    'origin': req.headers.origin,
    'mcp-protocol-version': req.headers['mcp-protocol-version']
  }, 'POST');

  const message = req.body;
  debugLog('📦 Message:', message, 'POST');

  if (!sessionId) {
    debugLog('❌ No session ID provided', null, 'ERROR');
    return res.status(400).json({
      jsonrpc: '2.0',
      error: {
        code: -32000,
        message: 'Missing sessionId parameter'
      },
      id: null
    });
  }

  if (!sseClients.has(sessionId)) {
    debugLog(`❌ Invalid session ID: ${shortId}`, null, 'ERROR');
    debugLog(`📊 Active sessions: ${Array.from(sseClients.keys()).map(id => id.substring(0, 8)).join(', ')}`, null, 'ERROR');
    return res.status(404).json({
      jsonrpc: '2.0',
      error: {
        code: -32000,
        message: 'Session not found'
      },
      id: message?.id || null
    });
  }

  // Log successful POST
  connectionLog.push({
    sessionId: shortId,
    event: 'post',
    method: message?.method,
    timestamp: new Date().toISOString()
  });

  try {
    const response = await handleMCPMessage(message);

    if (response) {
      debugLog(`✅ Generated response for ID ${response.id}`, response, 'MCP');

      // Send response via SSE
      const client = sseClients.get(sessionId).res;
      const sseMessage = `event: message\ndata: ${JSON.stringify(response)}\n\n`;

      debugLog(`📤 Sending SSE response to session ${shortId}`, null, 'POST');
      client.write(sseMessage);

      // Return 202 Accepted (response sent via SSE)
      res.status(202).end();
    } else {
      debugLog(`✅ Notification handled, returning 202`, null, 'POST');
      res.status(202).end();
    }
  } catch (error) {
    debugLog(`❌ Error handling message:`, error.message, 'ERROR');
    const errorResponse = {
      jsonrpc: '2.0',
      error: {
        code: -32000,
        message: error.message
      },
      id: message?.id || null
    };

    const client = sseClients.get(sessionId)?.res;
    if (client) {
      client.write(`event: message\ndata: ${JSON.stringify(errorResponse)}\n\n`);
    }
    res.status(202).end();
  }
});

// OPTIONS handler for /messages (CORS preflight)
app.options('/messages', (req, res) => {
  debugLog(`📋 OPTIONS /messages received`, null, 'HTTP');
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Title, MCP-Protocol-Version');
  res.status(204).end();
});

// MCP message handler
async function handleMCPMessage(message) {
  const { jsonrpc, method, params, id } = message;

  debugLog(`⚙️ Processing method: ${method}, id: ${id}`, null, 'MCP');

  if (jsonrpc !== '2.0') {
    throw new Error('Invalid JSON-RPC version');
  }

  // Handle notifications
  if (method && method.startsWith('notifications/')) {
    debugLog(`🔔 Notification: ${method}`, null, 'MCP');
    return null;
  }

  // Handle ping
  if (method === 'ping') {
    debugLog('🏓 PING received', null, 'MCP');
    return {
      jsonrpc: '2.0',
      result: 'pong',
      id
    };
  }

  // Handle initialize
  if (method === 'initialize') {
    debugLog('🔄 INITIALIZE request', params, 'MCP');

    return {
      jsonrpc: '2.0',
      result: {
        protocolVersion: '2025-11-25',
        capabilities: {
          tools: {
            listChanged: false
          }
        },
        serverInfo: {
          name: 'emacs-lisp-documentation',
          version: '1.0.0'
        }
      },
      id
    };
  }

  // Handle tools/list
  if (method === 'tools/list') {
    debugLog('🔧 TOOLS/LIST request', null, 'MCP');

    const tools = [
      {
        name: 'get_documentation',
        description: 'Get documentation for an Emacs Lisp function',
        inputSchema: {
          type: 'object',
          properties: {
            function_name: {
              type: 'string',
              description: 'Name of the Emacs Lisp function (e.g., "find-file", "org-mode", "rcd-command")'
            }
          },
          required: ['function_name']
        }
      },
      {
        name: 'list_functions_by_prefix',
        description: 'List Emacs Lisp functions that start with a given prefix',
        inputSchema: {
          type: 'object',
          properties: {
            prefix: {
              type: 'string',
              description: 'Function name prefix (e.g., "rcd-", "org-", "vc-")',
              default: 'rcd-'
            }
          },
          required: ['prefix']
        }
      },
      {
        name: 'search_functions',
        description: 'Search for Emacs Lisp functions by name (case insensitive)',
        inputSchema: {
          type: 'object',
          properties: {
            search_term: {
              type: 'string',
              description: 'Search term to look for in function names'
            }
          },
          required: ['search_term']
        }
      }
    ];

    return {
      jsonrpc: '2.0',
      result: {
        tools: tools
      },
      id
    };
  }

  // Handle tools/call
  if (method === 'tools/call') {
    const { name, arguments: args } = params;
    debugLog(`🔧 TOOL/CALL: ${name}`, args, 'MCP');

    if (name === 'get_documentation') {
      if (!args?.function_name) {
        throw new Error('function_name is required');
      }

      const doc = await emacsEval(`(documentation '${args.function_name})`);
      return {
        jsonrpc: '2.0',
        result: {
          content: [
            {
              type: 'text',
              text: doc || `No documentation found for ${args.function_name}`
            }
          ]
        },
        id
      };
    }

    if (name === 'list_functions_by_prefix') {
      if (!args?.prefix) {
        throw new Error('prefix is required');
      }

      const result = await emacsEval(`
        (let ((functions '()))
          (mapatoms (lambda (sym)
            (when (and (fboundp sym)
                      (string-prefix-p "${args.prefix}" (symbol-name sym)))
              (push (symbol-name sym) functions))))
          (format "%s" (sort functions 'string<)))
      `);

      const funcs = result
        .replace(/[()]/g, '')
        .split(/\s+/)
        .map(f => f.replace(/"/g, ''))
        .filter(f => f && f.length)
        .join('\n');

      return {
        jsonrpc: '2.0',
        result: {
          content: [
            {
              type: 'text',
              text: funcs || `No functions found with prefix "${args.prefix}"`
            }
          ]
        },
        id
      };
    }

    if (name === 'search_functions') {
      if (!args?.search_term) {
        throw new Error('search_term is required');
      }

      const result = await emacsEval(`
        (let ((functions '()))
          (mapatoms (lambda (sym)
            (when (and (fboundp sym)
                      (string-match-p "${args.search_term}" (symbol-name sym)))
              (push (symbol-name sym) functions))))
          (format "%s" (sort functions 'string<)))
      `);

      const funcs = result
        .replace(/[()]/g, '')
        .split(/\s+/)
        .map(f => f.replace(/"/g, ''))
        .filter(f => f && f.length)
        .join('\n');

      return {
        jsonrpc: '2.0',
        result: {
          content: [
            {
              type: 'text',
              text: funcs || `No functions found matching "${args.search_term}"`
            }
          ]
        },
        id
      };
    }

    throw new Error(`Unknown tool: ${name}`);
  }

  throw new Error(`Unknown method: ${method}`);
}

