### Bug Description

The outputSchame definition for this tool is as follows:
```json
{
    "properties": {
        "code": {
            "description": "Execution result code, 0: success, non-0: error",
            "type": "integer"
        },
        "data": {
            "properties": {
                "count": {
                    "default": 0,
                    "description": "Number of layers currently loaded",
                    "type": "integer"
                },
                "layers": {
                    "description": "Loaded layer information array",
                    "items": {
                        "description": "Layer information object",
                        "properties": {
                            "id": {
                                "default": "",
                                "description": "Layer ID",
                                "type": "string"
                            },
                            "locked": {
                                "description": "layer locked?",
                                "type": "boolean"
                            },
                            "url": {
                                "default": "",
                                "description": "Layer file path",
                                "type": "string",
                                "format": "uri"
                            },
                            "visible": {
                                "description": "layer visible?",
                                "type": "boolean"
                            }
                        },
                        "required": ["id"],
                        "type": "object"
                    },
                    "type": "array"
                }
            },
            "required": ["count"],
            "type": "object"
        },
        "msg": {
            "description": "When an execution error occurs, an error message is output. When successful, a success message or an empty message is output.",
            "type": "string"
        }
    },
    "required": ["code", "msg"],
    "type": "object"
}
```

Calling this tool returns the following results

```json
{
  "id": 9,
  "jsonrpc": "2.0",
  "result": {
    "content": [
      {
        "text": "{\"code\":0,\"data\":{\"count\":1,\"layers\":[{\"id\":\"{ebecad43-9b17-481a-bf16-2c072c7122a3}\",\"locked\":false,\"url\":\"file:///D:/测试数据/TLS1_去噪.LiData?load_option=0&layer_class=PointCloudLayerV2&file_as_type=POINTS_CLOUD_TYPE\",\"visible\":true}]},\"msg\":\"\"}",
        "type": "text"
      }
    ],
    "structuredContent": {
      "code": 0,
      "data": {
        "count": 1,
        "layers": [
          {
            "id": "{ebecad43-9b17-481a-bf16-2c072c7122a3}",
            "locked": false,
            "url": "file:///D:/测试数据/TLS1_去噪.LiData?load_option=0&layer_class=PointCloudLayerV2&file_as_type=POINTS_CLOUD_TYPE",
            "visible": true
          }
        ]
      },
      "msg": ""
    }
  }
}
```

However, when calling in cherry studio, an error will be reported, showing that `url` does not match the format `uri`. But I think this result is in line with the specification of the uri, I don't know what the problem is.

> [https://datatracker.ietf.org/doc/html/rfc3986](https://datatracker.ietf.org/doc/html/rfc3986)

